statement:
Think of an array with `n` cells, indexed `0` to `n - 1`. Each entry `[l, r]` of `ranges` covers every cell from `l` to `r`, both included; ranges may overlap, nest or repeat.

Return the cells that no range covers, grouped into maximal blocks of consecutive cells, as a list of `[start, end]` pairs (both inclusive):

- every uncovered cell lies in exactly one returned pair, and no covered cell lies in any;
- no two returned pairs touch, that is, no pair ends at `r1` while another starts at `r1 + 1`;
- the pairs are sorted by `start` in increasing order.

Return an empty list when every cell is covered.

validator:
function validate([n, ranges]) {
  if (!Number.isInteger(n) || n < 1 || n > 1e9) return 'n is between 1 and 10^9.';
  if (ranges.length > 1e6) return 'ranges has at most 10^6 entries.';
  for (const range of ranges) {
    if (range.length !== 2) return 'Each range is a pair [l, r].';
    const [l, r] = range;
    if (!Number.isInteger(l) || !Number.isInteger(r) || l < 0 || r > n - 1 || l > r) return 'Each range needs 0 <= l <= r <= n - 1.';
  }
  return null;
}

reference:
function findMaximalUncoveredRanges(n, ranges) {
  ranges.sort((a, b) => a[0] - b[0]);
  const result = [];
  let next = 0;

  for (const [start, end] of ranges) {
    if (start > next) {
      result.push([next, start - 1]);
    }
    next = Math.max(next, end + 1);
  }
  if (next < n) {
    result.push([next, n - 1]);
  }
  return result;
}

brute:
function findMaximalUncoveredRanges(n, ranges) {
  const cuts = new Set([0, n]);
  for (const [l, r] of ranges) { cuts.add(l); cuts.add(r + 1); }
  const points = [...cuts].sort((a, b) => a - b);
  const out = [];
  for (let k = 0; k + 1 < points.length; k++) {
    const lo = points[k], hi = points[k + 1] - 1;
    const covered = ranges.some(([l, r]) => l <= lo && hi <= r);
    if (covered) continue;
    if (out.length && out[out.length - 1][1] + 1 === lo) out[out.length - 1][1] = hi;
    else out.push([lo, hi]);
  }
  return out;
}

