function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = rand() < 0.5 ? 1000000000 : int(5000, 1000000000);
    const m = 2000;
    const maxLen = Math.max(1, Math.floor(n / int(1000, 4000)));
    const ranges = [];
    for (let i = 0; i < m; i++) {
      const l = int(0, n - 1);
      const r = Math.min(n - 1, l + int(0, maxLen));
      ranges.push([l, r]);
    }
    return [n, ranges];
  }
  const n = int(1, 20);
  const m = int(0, 6);
  const ranges = [];
  for (let i = 0; i < m; i++) {
    const l = int(0, n - 1);
    const r = rand() < 0.3 ? l : int(l, Math.min(n - 1, l + int(0, 6)));
    ranges.push([l, r]);
  }
  return [n, ranges];
}
